"""Ordered-storage interface.

The baseline library exposes a ``SortedList``; the branchable experiment engine
uses it for its public/auxiliary ordered views and adds the structures that the
protocol actually needs: a per-bank PIFO ordered by the immutable
``(rank, ordinal)`` key with O(1) removal (so cancellation and pushout stay
cheap on large backlogs) and a global rank-ordered view supporting
"how many live packets have a strictly smaller rank" in O(log n).

Both structures use a segmented (sqrt-decomposed) list: whole-backlog work is
never repeated per operation.
"""
from bisect import bisect_left as _bisect_left

_MAX_SEG = 192
_MIN_SEG = 32


class SortedList:
    """Drop-in ordered list kept for the baseline library API."""

    def __init__(self, iterable=None):
        self._items = []
        if iterable is not None:
            for item in iterable:
                self.add(item)

    def add(self, item):
        self._items.insert(_bisect_left(self._items, item), item)

    def pop(self, index=-1):
        return self._items.pop(index)

    def remove(self, item):
        self._items.remove(item)

    def clear(self):
        self._items.clear()

    def bisect_left(self, item):
        return _bisect_left(self._items, item)

    def __bool__(self):
        return bool(self._items)

    def __len__(self):
        return len(self._items)

    def __iter__(self):
        return iter(self._items)

    def __getitem__(self, index):
        return self._items[index]


class _Segmented:
    """Segmented ordered container.

    ``_keys`` holds one sorted list of keys per segment; ``_vals`` holds the
    matching payload objects.  Keys are compared with ``<``/``==`` only and are
    totally ordered.
    """

    __slots__ = ('_keys', '_vals', '_total', '_maxseg')

    def __init__(self, segments=None):
        self._keys = segments[0] if segments is not None else []
        self._vals = segments[1] if segments is not None else []
        self._total = 0
        self._maxseg = _MAX_SEG
        if segments is not None:
            for seg in self._vals:
                self._total += len(seg)

    # -- structural helpers -------------------------------------------------
    def _adopt(self, other):
        """Adopt another container's segments in sorted order (keys disjoint)."""
        keys, vals = self._keys, self._vals
        okeys, ovals = other._keys, other._vals
        i = j = 0
        nk = []
        nv = []
        while i < len(keys) and j < len(okeys):
            if keys[i][0] < okeys[j][0]:
                nk.append(keys[i]); nv.append(vals[i]); i += 1
            else:
                nk.append(okeys[j]); nv.append(ovals[j]); j += 1
        nk.extend(keys[i:]); nv.extend(vals[i:])
        nk.extend(okeys[j:]); nv.extend(ovals[j:])
        self._keys, self._vals = nk, nv
        self._total += other._total
        other._keys, other._vals, other._total = [], [], 0
        self._maybe_compact()

    def _maybe_compact(self):
        vals = self._vals
        if len(vals) < 2:
            return
        n = self._total
        limit = n // 16 + self._maxseg
        merged = False
        i = 0
        while i + 1 < len(vals):
            a, b = vals[i], vals[i + 1]
            if len(a) + len(b) <= limit or (len(a) < _MIN_SEG and len(b) < _MIN_SEG):
                ka, kb = self._keys[i], self._keys[i + 1]
                if ka[-1] < kb[0]:
                    vals[i] = a + b
                    self._keys[i] = ka + kb
                    del vals[i + 1]
                    del self._keys[i + 1]
                    merged = True
                    continue
            i += 1
        if merged and len(vals) > 1 and self._total > 4 * limit:
            self._rebalance()

    def _rebalance(self):
        flat = []
        for seg in self._vals:
            flat.extend(seg)
        size = self._total
        nseg = 1
        while nseg * nseg * 4 < size:
            nseg += 1
        step = (size + nseg - 1) // nseg
        if step < _MIN_SEG:
            step = _MIN_SEG
        self._vals = [flat[i:i + step] for i in range(0, size, step)]
        self._keys = [[v.key() for v in seg] for seg in self._vals]

    # -- ordered views ------------------------------------------------------
    def _find_segment(self, key):
        """Index of the (first) segment that could contain ``key``."""
        keys = self._keys
        lo, hi = 0, len(keys)
        while lo < hi:
            mid = (lo + hi) >> 1
            if keys[mid][-1] < key:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def count_lt(self, key):
        """Number of stored keys strictly smaller than ``key``."""
        keys = self._keys
        idx = self._find_segment(key)
        total = 0
        for i in range(idx):
            total += len(keys[i])
        if idx < len(keys):
            total += _bisect_left(keys[idx], key)
        return total

    def count_le(self, key):
        """Number of stored keys smaller than or equal to ``key``."""
        keys = self._keys
        lo, hi = 0, len(keys)
        while lo < hi:
            mid = (lo + hi) >> 1
            if key < keys[mid][0]:
                hi = mid
            else:
                lo = mid + 1
        idx = lo
        total = 0
        for i in range(idx):
            total += len(keys[i])
        if idx < len(keys):
            total += _bisect_left(keys[idx], key) + 1
            seg = keys[idx]
            p = _bisect_left(keys[idx], key) + 1
            while p < len(seg) and not (key < seg[p]):
                p += 1
            total = total - (_bisect_left(keys[idx], key) + 1) + p
        return total

    def items(self):
        for seg in self._vals:
            for v in seg:
                yield v

    def keys_sorted(self):
        for seg in self._keys:
            for k in seg:
                yield k

    def __bool__(self):
        return self._total != 0

    def __len__(self):
        return self._total

    def __iter__(self):
        return self.items()

    # -- mutation -----------------------------------------------------------
    def add(self, value):
        key = value.key()
        keys, vals = self._keys, self._vals
        idx = self._find_segment(key)
        if idx >= len(keys) or keys[idx][0] < key:
            keys.insert(idx, [key])
            vals.insert(idx, [value])
            self._total += 1
            if len(vals) * len(vals) > 4 * self._total + 4096:
                self._rebalance()
            return
        seg_k = keys[idx]
        p = _bisect_left(seg_k, key)
        seg_k.insert(p, key)
        vals[idx].insert(p, value)
        self._total += 1
        if len(seg_k) > self._maxseg:
            half = len(seg_k) >> 1
            keys.insert(idx + 1, seg_k[half:])
            vals.insert(idx + 1, vals[idx][half:])
            del seg_k[half:]
            del vals[idx][half:]
            if len(vals) * len(vals) > 4 * self._total + 4096:
                self._rebalance()

    def remove(self, value):
        key = value.key()
        keys, vals = self._keys, self._vals
        idx = self._find_segment(key)
        if idx >= len(keys):
            raise KeyError('missing key')
        seg_k = keys[idx]
        seg_v = vals[idx]
        p = _bisect_left(seg_k, key)
        while p < len(seg_k) and not (key < seg_k[p]):
            if seg_v[p] is value:
                del seg_k[p]
                del seg_v[p]
                self._total -= 1
                if not seg_v:
                    del keys[idx]
                    del vals[idx]
                return
            p += 1
        raise KeyError('missing value')

    def clear(self):
        self._keys = []
        self._vals = []
        self._total = 0

    def peek(self):
        """Smallest ``(rank, ordinal)`` payload, without removing it."""
        if not self._total:
            return None
        return self._vals[0][0]

    def pop_first(self):
        if not self._total:
            return None
        vals, keys = self._vals, self._keys
        seg_v, seg_k = vals[0], keys[0]
        v = seg_v.pop(0)
        seg_k.pop(0)
        self._total -= 1
        if not seg_v:
            del vals[0]
            del keys[0]
        return v

    def pop_last(self):
        if not self._total:
            return None
        vals, keys = self._vals, self._keys
        i = len(vals) - 1
        v = vals[i].pop()
        keys[i].pop()
        self._total -= 1
        if not vals[i]:
            del vals[i]
            del keys[i]
        return v

    def drop_last(self, count):
        """Remove and return up to ``count`` largest payloads (descending)."""
        out = []
        for _ in range(count):
            v = self.pop_last()
            if v is None:
                break
            out.append(v)
        return out

    def segments(self):
        return (self._keys, self._vals)


class PifoStore(_Segmented):
    """Per-bank PIFO ordered by ``(rank, ordinal)`` with O(1) index removal."""

    __slots__ = ('_keys', '_vals', '_total', '_maxseg')

    def __init__(self, segments=None):
        _Segmented.__init__(self, segments)

    def remove_at(self, index):
        """Remove the payload at ordered ``index`` using the cached position."""
        value = None
        keys, vals = self._keys, self._vals
        i = 0
        acc = index
        while i < len(vals):
            if acc < len(vals[i]):
                value = vals[i][acc]
                del vals[i][acc]
                del keys[i][acc]
                break
            acc -= len(vals[i])
            i += 1
        if value is None:
            raise IndexError('pifo index')
        self._total -= 1
        if i < len(vals) and not vals[i]:
            del vals[i]
            del keys[i]
        # Shift cached positions after the removed slot.
        j = i
        while j < len(vals):
            for v in vals[j]:
                if v.pos > index:
                    v.pos -= 1
            j += 1
        return value


class RankIndex(_Segmented):
    """Global live-set rank index supporting strict-rank prefix counts."""

    __slots__ = ('_keys', '_vals', '_total', '_maxseg')

    def __init__(self, segments=None):
        _Segmented.__init__(self, segments)


def merge_segments(left, right):
    """Merge two disjoint-or-ordered segment pairs into one (used by restore)."""
    keys = left[0] + right[0]
    vals = left[1] + right[1]
    merged = _Segmented((keys, vals))
    if len(vals) > 1:
        merged._rebalance()
    return merged.segments()
